import React from "react";

const formatResource = (booking) => {
  const resource = booking.resource;
  if (!resource) return `Resource #${booking.resource_id}`;
  return resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;
};

const formatBlock = (booking) => booking.resource?.is_extra_center ? "Extra Center" : booking.resource?.block?.name ? `Block ${booking.resource.block.name}` : booking.block_id ? `Block #${booking.block_id}` : "-";
const formatRole = (role) => role === "admin" ? "HOD / Admin" : role === "teacher" ? "Teacher" : "Student";

const AdminBookingTable = ({ bookings = [], showActions = false, onApprove, onReject, detailed = false }) => (
  <div className="responsive-table">
    <table>
      <thead>
        <tr>
          <th>Requester</th>
          <th>Role</th>
          {detailed ? <th>UID</th> : null}
          <th>Department</th>
          <th>Block</th>
          <th>Resource</th>
          <th>Date</th>
          <th>Time</th>
          {detailed ? <th>Purpose</th> : null}
          <th>Status</th>
          {detailed ? <th>Created At</th> : null}
          {detailed ? <th>Decision Time</th> : null}
          {detailed ? <th>Rejection Reason</th> : null}
          {showActions ? <th>Actions</th> : null}
        </tr>
      </thead>
      <tbody>
        {!bookings.length ? (
          <tr>
            <td colSpan={showActions ? 14 : 13} className="empty-table-cell">No booking records found.</td>
          </tr>
        ) : bookings.map((booking) => (
          <tr key={booking.id}>
            <td>{booking.name || booking.user?.name || booking.user?.username || "User"}</td>
            <td>{formatRole(booking.user?.role)}</td>
            {detailed ? <td>{booking.user?.uid || booking.user?.username || "-"}</td> : null}
            <td>{booking.department || booking.user?.department || "-"}</td>
            <td>{formatBlock(booking)}</td>
            <td>{formatResource(booking)}</td>
            <td>{booking.booking_date}</td>
            <td>{String(booking.start_time).slice(0, 5)} - {String(booking.end_time).slice(0, 5)}</td>
            {detailed ? <td>{booking.purpose || "-"}</td> : null}
            <td><span className={`status-pill ${booking.status}`}>{booking.status}</span></td>
            {detailed ? <td>{booking.created_at ? new Date(booking.created_at).toLocaleString() : "-"}</td> : null}
            {detailed ? <td>{booking.decision_at ? new Date(booking.decision_at).toLocaleString() : "-"}</td> : null}
            {detailed ? <td>{booking.rejection_reason || "-"}</td> : null}
            {showActions ? (
              <td>
                <div className="table-actions">
                  <button className="approve-action" type="button" onClick={() => onApprove(booking.id)}>Approve</button>
                  <button className="reject-action" type="button" onClick={() => onReject(booking)}>Reject</button>
                </div>
              </td>
            ) : null}
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export default AdminBookingTable;
